  (1506, $$Los sonidos distrajeron al Capitán Bouchard de sus pensamientos descontentos.$$, $$El Capitán Bouchard pudo pensar sus ideas contrariadas sin interrupción.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1507, $$Los sonidos distrajeron al capitán Bouchard de sus pensamientos descontentos.$$, $$Los pensamientos del capitán Bouchard se detuvieron a causa de unos ruidos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1508, $$Los sonidos distrajeron al Capitán Bouchard de sus pensamientos descontentos.$$, $$Los gritos del cachorro sacudieron al Capitán de sus reflexiones.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1509, $$Pero no puedo olvidar que, cuando no era mejor que un esclavo en la casa de tu tío en Barbados, me utilizaste con una cierta amabilidad.$$, $$Me trataste amablemente cuando era esclavo en Barbados.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1510, $$Pero no puedo olvidar que, cuando no era mejor que un esclavo en la casa de tu tío en Barbados, me utilizaste con una cierta amabilidad.$$, $$Fuiste increíblemente cruel conmigo, y me trataste peor que a una basura.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1511, $$Pero no puedo olvidar que, cuando no era mejor que un esclavo en la casa de tu tío en Barbados, me utilizaste con una cierta amabilidad.$$, $$Tu tío me golpeaba duro cada día cuando me humillaba.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
