  (1513, $$Me complacerá llegar a Buenos Aires. El Capitán Bouchard apartó un pergamino bajo la mirada de Calderón.$$, $$El Capitán Bouchard le dio a Calderón un documento.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1516, $$Ahí, a no más de tres millas de distancia, había tierra, una pared irregular de intenso color verde que llenaba el horizonte occidental.$$, $$La isla a la que se estaban acercando estaba inhabitada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1517, $$Ahí, a no más de tres millas de distancia, había tierra, una pared irregular de intenso color verde que llenaba el horizonte occidental.$$, $$No podían ver ninguna tierra por millas, solo un océano sin fin.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1518, $$Soy el enviado de Su Majestad a estas partes bárbaras, y al pariente cercano de mi Señor Sunderland.$$, $$Su Majestad tiene enviados, y yo soy uno de ellos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1519, $$Soy el enviado de Su Majestad a estas partes bárbaras, y al pariente cercano de mi Señor Sunderland.$$, $$Su Majestad me envió acá hace una semana.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1520, $$Soy el enviado de Su Majestad a estas partes bárbaras, y el pariente cercano de mi Señor Sunderland.$$, $$No recibo órdenes de Su Majestad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1521, $$Te lo debía, o así creí, dijo él.$$, $$Nunca pensó que te debiera nada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
