  (1865, $$No sabía si los hombres cambiarían de opinión respecto a López, con el pánico originado por González.$$, $$No había dudas en su mente sobre cómo los hombres en pánico verían las cosas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1927, $$Debo regresar al Coronel Rodríguez para recibir mis órdenes, les dijo.$$, $$Les dijo que acudiría al Coronel Rodríguez a buscar órdenes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1928, $$Debo regresar al Coronel Rodríguez para recibir mis órdenes, les dijo.$$, $$Les dijo que iría al Coronel Rodríguez mañana por sus órdenes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (1929, $$En un instante, el capitán Bouchard vio lo que tenían en mente.$$, $$El Capitán Bouchard leyó apresuradamente lo que las otras personas estaban pensando.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
