  (3029, $$Informe de inteligencia, interrogatorio de Binalshibh, 1 de octubre de 2002.$$, $$A Binalshibh nunca se le habló y desapareció.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3030, $$Mihdhar recibe un nuevo visado para los Estados Unidos dos días después del encuentro entre la CIA y el FBI en Nueva York.$$, $$Mihdhar tenía una visa de los Estados Unidos para ingresar al país.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3031, $$Mihdhar recibe un nuevo visado para los Estados Unidos dos días después del encuentro entre la CIA y el FBI en Nueva York.$$, $$Mihdhar nunca obtuvo una visa, por lo que nunca vino a Estados Unidos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
