  (3039, $$En el caso de American 11, la última comunicación normal del avión fue a las 8:13 a. m.$$, $$Hubo comunicación proveniente de American 11.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3040, $$En el caso de American 11, la última comunicación normal del avión fue a las 8:13 a. m.$$, $$Hubo comunicación del American 11 cada 5 minutos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
