  (3047, $$Estas capacidades eran insuficientes, pero se hizo poco para expandirlas o reformarlas.$$, $$Hicieron todo lo posible para revisar todo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3054, $$Incluso en esa situación, la restricción obliga a ejecutar la información a través de la pantalla OIPR.$$, $$La pantalla OIPR no hace otra cosa que darles a los pasajeros información sobre los horarios de vuelo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3056, $$Incluso en esa situación, la restricción obliga a ejecutar la información a través de la pantalla OIPR.$$, $$La pantalla del OIPR procesa alguna información.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3057, $$El 9 de septiembre llegaron noticias dramáticas de Afganistán.$$, $$Recibimos noticias de Afganistán.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
