  (3200, $$Esta declaración se emitió el día después de que los mercados financieros volvieran a abrir.$$, $$Los mercados estaban cerrados porque existían problemas de liquidez generalizados.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3201, $$Bandar al Hazmi continuó su entrenamiento en Arizona Aviation, con viajes intermitentes a su país, Arabia Saudí, antes de irse de los Estados Unidos por última vez en enero del 2000.$$, $$Bandar al Hazmi vino a los EE. UU. 18 veces.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3202, $$Bandar al Hazmi continuó su entrenamiento en Arizona Aviation, con viajes intermitentes a su país, Arabia Saudí, antes de irse de los Estados Unidos por última vez en enero del 2000.$$, $$Bandar al Hazmi llegó a Estados Unidos en el año 2000.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3203, $$Bandar al Hazmi continuó su entrenamiento en Arizona Aviation, con viajes intermitentes a su país, Arabia Saudí, antes de irse de los Estados Unidos por última vez en enero del 2000.$$, $$Bandar al Hazmi nunca viajó a los Estados Unidos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3204, $$Para la necesidad de pasar de la necesidad de saber a la necesidad de compartir, ver el testimonio de James Steinberg, 14 de octubre de 2003.$$, $$James Steinberg testificó que se necesitaba compartir más.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3205, $$Para la necesidad de pasar de la necesidad de saber a la necesidad de compartir, ver el testimonio de James Steinberg, 14 de octubre de 2003.$$, $$James Steinberg se mantuvo firme sobre que el intercambio de datos se debía evitar a toda costa.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3206, $$Para la necesidad de pasar de la necesidad de saber a la necesidad de compartir, ver el testimonio de James Steinberg, 14 de octubre de 2003.$$, $$La razón principal por la que debía conocerse previamente era la amenaza de que los analistas fraudulentos filtraran secretos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3207, $$Las dotaciones de guardia estaban compuestas por un capitán o teniente y cinco bomberos.$$, $$En otras ciudades, las compañías escalonadas a menudo contenían hasta 8 miembros.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
