  (3555, $$El acceso a nuestro recinto estará abierto a cualquier persona que disponga de una computadora y un módem.$$, $$La gente no necesita nada para acceder a los terrenos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3556, $$El acceso a nuestro recinto estará abierto a cualquier persona que disponga de una computadora y un módem.$$, $$Se necesitan una computadora y un módem para entrar en el recinto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3557, $$El acceso a nuestro recinto estará abierto a cualquier persona que disponga de una computadora y un módem.$$, $$Las personas necesitan llevar consigo su computadora y su módem mientras ingresan a los terrenos, para tener acceso.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3558, $$Le invitamos a participar en Futures for Children patrocinando a un niño indígena estadounidense o haciéndose socio para apoyar nuestros proyectos de educación comunitaria.$$, $$Si elige patrocinar a un niño indígena americano, no podrá participar en Futures for Children.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
