  (3631, $$Las casillas estarán marcadas con los nombres de Cassie, Corey, Rachel, Isaiah, Kelly, Kyle y los otros estudiantes de Columbine High School que perdieron la vida a principios de este año.$$, $$El instituto Columbine cerró sus puertas después de que algunos estudiantes perdieran sus vidas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3632, $$Las casillas estarán marcadas con los nombres de Cassie, Corey, Rachel, Isaiah, Kelly, Kyle y los otros estudiantes de Columbine High School que perdieron la vida a principios de este año.$$, $$No se realizará un monumento para Cassie, una de las alumnas que murió en Columbine High School.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
  (3633, $$Para que las bibliotecas de la Universidad IUPUI tengan colecciones, acceso y servicios que cumplan con sus expectativas, se requieren amigos y socios dentro de la Universidad y en toda la comunidad, en todo el estado y en toda la nación.$$, $$La IUPUI no tiene ningún tipo de financiación o ayuda voluntaria.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_02.jsonl$$),
